composer.css:
.cg-composer{position:relative;box-sizing:border-box;width:768px;font-family:var(--cg-font, Inter, sans-serif);font-size:16px;line-height:24px;font-weight:400;color:var(--cg-text, #ededed);background:var(--cg-composer, #1b1b1b);border-radius:26px;box-shadow:inset 0 0 1px 0 rgba(255,255,255,0.2);-webkit-font-smoothing:antialiased;font-optical-sizing:none}
.cg-composer svg{display:block;flex:none}
.cg-grid{container-name:composer-footer;display:grid;grid-template-columns:36px minmax(0,1fr) auto;column-gap:8px;align-items:center;box-sizing:border-box;width:768px;height:52px;padding:8px;line-height:24px;font-weight:400;color:var(--cg-text, #ededed);-webkit-font-smoothing:antialiased}
.cg-plus{grid-column:1;grid-row:1;width:36px;height:36px;box-sizing:border-box;border-radius:9999px;display:flex;align-items:center;justify-content:center;color:var(--cg-text, #ededed)}
.cg-text{grid-column:2;grid-row:1;min-width:0;margin:5px 0;line-height:26px;min-height:26px;white-space:pre;overflow:hidden;text-overflow:ellipsis;color:var(--cg-text, #ededed)}
.cg-ph{color:var(--cg-text-2, #afafaf)}
.cg-prompt:not(:empty)~.cg-ph{display:none}
.cg-caret{display:inline-block;width:1.5px;height:20px;margin-left:1px;vertical-align:-4px;background:var(--cg-text, #ededed)}
.cg-tools{grid-column:3;grid-row:1;display:flex;align-items:center;justify-content:flex-end}
.cg-model{height:36px;box-sizing:border-box;display:flex;align-items:center;gap:6px;padding:0 14px 0 12px;border-radius:18px;line-height:26px;color:var(--cg-text-2, #afafaf);white-space:nowrap}
.cg-ibtn{width:36px;height:36px;box-sizing:border-box;display:flex;align-items:center;justify-content:center;border-radius:9999px;color:var(--cg-text, #ededed)}
.cg-go{width:36px;height:36px;margin-left:8px;box-sizing:border-box;display:flex;align-items:center;justify-content:center;border-radius:9999px;background:var(--cg-accent, #2c67c5);color:#fff}
.cg-send{display:none}
.cg-composer:has(.cg-prompt:not(:empty)) .cg-voice,.cg-composer:has(.cg-chip) .cg-voice{display:none}
.cg-composer:has(.cg-prompt:not(:empty)) .cg-send,.cg-composer:has(.cg-chip) .cg-send{display:flex}
/* multi-line layout: see composer.multiline_rule */
.cg-composer.is-multiline,.cg-composer:has(.cg-chip){border-radius:28px}
.cg-composer.is-multiline .cg-grid,.cg-composer:has(.cg-chip) .cg-grid{height:auto;grid-template-rows:auto 36px;column-gap:8px;row-gap:16px;padding:0 8px 8px}
.cg-composer.is-multiline .cg-text,.cg-composer:has(.cg-chip) .cg-text{grid-column:1/-1;grid-row:1;margin:0 -8px;padding:15px 18px 0;white-space:pre-wrap;overflow:visible;max-height:216px}
.cg-composer.is-multiline .cg-plus,.cg-composer:has(.cg-chip) .cg-plus{grid-row:2}
.cg-composer.is-multiline .cg-tools,.cg-composer:has(.cg-chip) .cg-tools{grid-row:2}
